import numpy as np
def _digest(values, rows, cols):
    array = np.asarray(values, dtype=float)
    if cols == 0:
        if array.ndim != 1 or array.shape[0] != rows:
            return -1.0
    elif array.shape != (rows, cols):
        return -1.0
    flat = array.ravel()
    phase = np.cos(np.arange(flat.size, dtype=float) + 1.0)
    return float(flat.size) + float(np.sum(np.abs(flat)) + flat @ phase)
assert np.allclose(_digest(solve_epigenetic_equilibria(0.5, 4.0, 0.11), 3, 2), target)

